"""Pure-Python git metadata detection.

This module reads git's internal filesystem data structures directly
(``.git/HEAD``, ``.git/refs``, ``.git/packed-refs``, ``.git/config``) instead
of shelling out to the ``git`` executable.  This avoids the cost and fragility
of subprocess calls and works even in environments where ``git`` is not on the
``PATH``.
"""
from __future__ import annotations

import configparser
import logging
from pathlib import Path

log = logging.getLogger(__name__)

_REFS_TAGS_PREFIX = "refs/tags/"
_REFS_HEADS_PREFIX = "refs/heads/"


def _find_git_dir(path: str) -> Path | None:
    """Traverse upward from *path* to locate the git directory.

    Returns the ``.git`` directory as a :class:`~pathlib.Path`.  When ``.git``
    is a file (a linked worktree), the ``gitdir:`` pointer it contains is
    resolved (absolute, or relative to the ``.git`` file's parent) and returned.
    Returns ``None`` when no ``.git`` entry is found in the hierarchy.
    """
    start = Path(path)
    for directory in (start, *start.parents):
        git_path = directory / ".git"
        if git_path.is_dir():
            return git_path
        if git_path.is_file():
            try:
                content = git_path.read_text().strip()
            except OSError:
                return None
            for line in content.splitlines():
                if line.startswith("gitdir:"):
                    pointer = line[len("gitdir:") :].strip()
                    pointer_path = Path(pointer)
                    if pointer_path.is_absolute():
                        return pointer_path
                    return (git_path.parent / pointer_path).resolve()
            return None
    return None


def _read_head_content(git_dir: Path) -> str | None:
    """Return the trailing-whitespace-stripped content of ``git_dir/HEAD``.

    Returns ``None`` when ``HEAD`` does not exist.
    """
    head = git_dir / "HEAD"
    if not head.exists():
        return None
    return head.read_text().rstrip()


def _resolve_ref(git_dir: Path, ref: str) -> str | None:
    """Resolve a git ref (e.g. ``refs/heads/main``) to a commit SHA.

    The loose file at ``git_dir/ref`` is checked first; if absent, the ref is
    looked up in ``git_dir/packed-refs``.  Returns ``None`` when the ref cannot
    be found in either location.
    """
    loose = git_dir / ref
    if loose.exists():
        return loose.read_text().strip() or None

    packed = git_dir / "packed-refs"
    if packed.exists():
        for raw_line in packed.read_text().splitlines():
            line = raw_line.strip()
            if not line or line.startswith("#") or line.startswith("^"):
                continue
            parts = line.split(" ", 1)
            if len(parts) == 2 and parts[1] == ref:
                return parts[0]
    return None


def _read_head_sha(git_dir: Path) -> str | None:
    """Return the commit SHA that HEAD currently points to.

    Handles both detached HEAD (a raw SHA in ``HEAD``) and symbolic refs
    (``ref: refs/heads/<branch>``).  Returns ``None`` when ``HEAD`` is missing.
    """
    content = _read_head_content(git_dir)
    if content is None:
        return None
    if content.startswith("ref:"):
        ref = content[len("ref:") :].strip()
        return _resolve_ref(git_dir, ref)
    return content


def _find_tag_in_packed_refs(git_dir: Path, sha: str) -> str | None:
    """Return the tag name in ``git_dir/packed-refs`` that points at *sha*.

    Lightweight tags carry the commit SHA directly on their
    ``<sha> refs/tags/<name>`` line.  Annotated tags carry the tag object SHA on
    that line and the peeled commit SHA on the following ``^<sha>`` line.

    Returns the tag name (the part after ``refs/tags/``), or ``None`` when
    ``packed-refs`` is absent, the SHA is not associated with any tag, or the
    matching ref is not under ``refs/tags/``.
    """
    packed = git_dir / "packed-refs"
    if not packed.exists():
        return None

    prev_ref: str | None = None
    for raw_line in packed.read_text().splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("^"):
            # Dereference line for an annotated tag: the peeled commit SHA.
            peeled = line[1:].strip()
            if peeled == sha and prev_ref is not None:
                if prev_ref.startswith(_REFS_TAGS_PREFIX):
                    return prev_ref[len(_REFS_TAGS_PREFIX) :]
                return None
            continue
        parts = line.split(" ", 1)
        if len(parts) != 2:
            prev_ref = None
            continue
        obj_sha, ref = parts[0], parts[1]
        if obj_sha == sha:
            if ref.startswith(_REFS_TAGS_PREFIX):
                return ref[len(_REFS_TAGS_PREFIX) :]
            return None
        prev_ref = ref
    return None


def get_git_version(git_dir: Path) -> str | None:
    """Return the current commit SHA, or ``None`` when HEAD is missing."""
    return _read_head_sha(git_dir)


def get_git_branch(git_dir: Path) -> str | None:
    """Return the current branch name from HEAD's symbolic ref.

    Strips the ``refs/heads/`` prefix.  Returns ``None`` in detached HEAD state
    (HEAD holds a raw SHA) or when HEAD does not exist.
    """
    content = _read_head_content(git_dir)
    if content is None:
        return None
    if content.startswith("ref:"):
        ref = content[len("ref:") :].strip()
        if ref.startswith(_REFS_HEADS_PREFIX):
            return ref[len(_REFS_HEADS_PREFIX) :]
        return ref
    return None


def get_git_tag(git_dir: Path) -> str | None:
    """Return the tag name pointing at the current commit.

    Loose tag files under ``git_dir/refs/tags/`` are searched recursively first,
    then ``packed-refs`` is consulted as a fallback.  Returns the tag name
    relative to ``refs/tags/``, or ``None`` when no matching tag is found or
    HEAD is missing.
    """
    sha = _read_head_sha(git_dir)
    if sha is None:
        return None

    tags_dir = git_dir / "refs" / "tags"
    if tags_dir.is_dir():
        for tag_file in sorted(tags_dir.rglob("*")):
            if tag_file.is_file() and tag_file.read_text().strip() == sha:
                return tag_file.relative_to(tags_dir).as_posix()

    return _find_tag_in_packed_refs(git_dir, sha)


